<?php require __DIR__.'/../app/bootstrap.php';admin_required();$orders=db()->query('SELECT id,order_number,customer_name,phone,total,status,payment_status,created_at FROM orders ORDER BY id DESC LIMIT 250')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Orders — NEXT TECH Admin</title><link rel="stylesheet" href="<?=e(url('assets/css/style.css'))?>"></head><body class="admin-body"><aside class="admin-sidebar"><a class="wordmark" href="<?=e(url('admin/index.php'))?>"><span>NEXT</span> <b>TECH</b></a><a href="<?=e(url('admin/index.php'))?>">Dashboard</a><a href="<?=e(url('admin/products.php'))?>">Products</a><a href="<?=e(url('admin/categories.php'))?>">Categories</a><a class="active" href="<?=e(url('admin/orders.php'))?>">Orders</a><a href="<?=e(url('index.php'))?>">View Store</a><a href="<?=e(url('admin/logout.php'))?>">Logout</a></aside><main class="admin-main"><div class="admin-top"><h1>Orders</h1></div><div class="admin-panel table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Phone</th><th>Total</th><th>Payment</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=e($o['order_number'])?><br><small><?=e(date('d M Y',strtotime($o['created_at'])))?></small></td><td><?=e($o['customer_name'])?></td><td><?=e($o['phone'])?></td><td><?=money($o['total'])?></td><td><?=e($o['payment_status'])?></td><td><?=e(str_replace('_',' ',$o['status']))?></td><td><a href="<?=e(url('admin/order-view.php?id='.(int)$o['id']))?>">View / Update</a></td></tr><?php endforeach;?></tbody></table><?php if(!$orders):?><p>No orders received yet.</p><?php endif;?></div></main></body></html>